∀ {I : Type u} {J : Type v} {forward : I → J} {inverse : J → I} {left_inv : ∀ (i : I), inverse (forward i) = i}
  {right_inv : ∀ (j : J), forward (inverse j) = j} {forward_1 : I → J} {inverse_1 : J → I}
  {left_inv_1 : ∀ (i : I), inverse_1 (forward_1 i) = i} {right_inv_1 : ∀ (j : J), forward_1 (inverse_1 j) = j},
  { forward := forward, inverse := inverse, left_inv := left_inv, right_inv := right_inv } =
      { forward := forward_1, inverse := inverse_1, left_inv := left_inv_1, right_inv := right_inv_1 } →
    forward = forward_1 ∧ inverse = inverse_1

∀ {Seed : Type u} {Kappa : Seed → Type v} {Sigma : Seed → Type w} {State : Seed → Type z}
  {admissible : (seed : Seed) → Kappa seed → Sigma seed → Prop}
  {realize : (seed : Seed) → (k : Kappa seed) → (s : Sigma seed) → admissible seed k s → State seed}
  {Kappa_1 : Seed → Type v} {Sigma_1 : Seed → Type w} {State_1 : Seed → Type z}
  {admissible_1 : (seed : Seed) → Kappa_1 seed → Sigma_1 seed → Prop}
  {realize_1 : (seed : Seed) → (k : Kappa_1 seed) → (s : Sigma_1 seed) → admissible_1 seed k s → State_1 seed},
  { Kappa := Kappa, Sigma := Sigma, State := State, admissible := admissible, realize := realize } =
      { Kappa := Kappa_1, Sigma := Sigma_1, State := State_1, admissible := admissible_1, realize := realize_1 } →
    Kappa = Kappa_1 ∧ Sigma = Sigma_1 ∧ State = State_1 ∧ admissible ≍ admissible_1 ∧ realize ≍ realize_1
